'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {definitiveBookingRejection} from '@/lib/pending-booking';
import type {GuestAction,GuestReceipt,GuestRequestStatus} from '@/lib/guests';
type Marker={request:string;action:GuestAction;target:string|null;expectedVersion:number|null};
const uuid=/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i;
function validMarker(v:unknown,action:GuestAction):v is Marker{if(!v||typeof v!=='object')return false;const m=v as Marker;return Object.keys(m).sort().join(',')==='action,expectedVersion,request,target'&&m.action===action&&uuid.test(m.request)&&(m.target===null||uuid.test(m.target))&&(m.expectedVersion===null||Number.isSafeInteger(m.expectedVersion)&&m.expectedVersion>=0)&&(action==='save_guest_profile'?m.target===null?m.expectedVersion===null:Number(m.expectedVersion)>0:m.target!==null&&m.expectedVersion!==null)}
// Only request routing metadata survives a reload. Contact values remain in
// memory until the server confirms a save; recovery reads a scoped receipt.
export function useGuestRequest({storageKey,action,tenant,property,onBusyChange}:{storageKey:string;action:GuestAction;tenant:string;property:string;onBusyChange:(busy:boolean)=>void}){
 const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(storageKey);if(!raw)return {marker:null,error:''};const value:unknown=JSON.parse(raw);if(!validMarker(value,action))throw Error();return {marker:value,error:''}}catch{return {marker:null,error:'The saved guest request cannot be read. Reconcile this property’s records before creating another request.'}}});
 const [marker,setMarker]=useState<Marker|null>(initial.marker),[resuming,setResuming]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState('');const lock=useRef(false),alive=useRef(true),busyCallback=useRef(onBusyChange);
 useEffect(()=>{busyCallback.current=onBusyChange},[onBusyChange]);useEffect(()=>{alive.current=true;return()=>{alive.current=false;if(lock.current)busyCallback.current(false)}},[]);
 function clear(){sessionStorage.removeItem(storageKey);setMarker(null);setResuming(false)}
 async function task(fn:()=>Promise<void>){if(lock.current||initial.error)return;lock.current=true;setBusy(true);busyCallback.current(true);setError('');setNotice('');try{await fn()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to save guest details.')}finally{lock.current=false;if(alive.current){setBusy(false);busyCallback.current(false)}}}
 async function receipt(request:string){return hotelRpc<GuestRequestStatus>('guest_request_status',{p_tenant:tenant,p_property:property,p_request:request})}
 async function confirmed(status:GuestRequestStatus,onSaved:(receipt:GuestReceipt)=>Promise<void>,expected:Marker){const result=status.result;const resultId=action==='save_guest_profile'?result?.guest_id:result?.reservation_id;if(status.action!==action||!result||!Number.isSafeInteger(result.version)||result.version<1||typeof resultId!=='string'||!uuid.test(resultId)||expected.target!==null&&expected.target!==resultId)throw Error('The saved receipt does not match this record. Reconcile the request before continuing.');if(!alive.current)return;clear();await onSaved(result)}
 async function check(onSaved:(receipt:GuestReceipt)=>Promise<void>){if(!marker)return;await task(async()=>{const status=await receipt(marker.request);if(status.found){await confirmed(status,onSaved,marker)}else if(alive.current){setResuming(true);setNotice('No saved receipt was found. Review or re-enter the details below. The same request identity will be reused.')}})}
 async function save(target:string|null,expectedVersion:number|null,params:Record<string,unknown>,onSaved:(receipt:GuestReceipt)=>Promise<void>,onRejected:()=>void){await task(async()=>{const recovering=marker!==null;const next:Marker=marker?{...marker,expectedVersion}:{request:crypto.randomUUID(),action,target,expectedVersion};if(!validMarker(next,action)||next.target!==target)throw Error('The guest request is incomplete. Refresh this record.');sessionStorage.setItem(storageKey,JSON.stringify(next));setMarker(next);setResuming(false);const command={...params,p_request:next.request};
   let result:GuestReceipt;try{result=await hotelRpc<GuestReceipt>(action,{p_tenant:tenant,p_property:property,...command})}catch(e){if(definitiveBookingRejection(e)){const status=await receipt(next.request);if(status.found){await confirmed(status,onSaved,next);return}if(alive.current){if(recovering){setResuming(true);setNotice('The earlier request is still unresolved. Correct the reviewed details using this same request identity, or check its result again.')}else clear();onRejected()}throw e}throw Error('The save result is uncertain. Check the saved request below before creating another record.')}
   await confirmed({found:true,action,result},onSaved,next);
  })}
 return {marker,busy,error,notice,resuming,blocked:!!initial.error,check,save};
}
export function GuestRecovery({busy,onCheck}:{busy:boolean;onCheck:()=>void}){return <div className="pilot-notice"><h3>Recover guest details request</h3><p>An interrupted save is recorded. Check its result before editing. Contact details are not stored in this browser’s recovery record.</p><button className="primary" disabled={busy} onClick={onCheck}>Check saved guest request</button></div>}
